"""Expected output of tests/t447_stats_special.a. The tables in the test are regenerated by mk_t447.py (run it separately: it takes a few seconds);
every table row has to match the 70 digit reference to the stated tolerance, so the expected lines are the verdicts. The edge cases are the mathematical limits."""
import sys
out = []
for name, tol in (('erf', '1e-15'), ('erfc', '1e-15'), ('lgamma', '1e-15'), ('gamma', '1e-15'), ('digamma', '1e-14'), ('incGammaP / incGammaQ', '1e-13'),
                  ('incBeta / betaSf', '1e-12'), ('lbeta', '1e-14'), ('erfInv', '1e-14'), ('stdNormalQuantile', '1e-14')):
    out.append('%s: all within %s: 1' % (name, tol))
out += [
 'erf is odd and erf + erfc = 1 on 41 points: 0 violations',
 'gamma(n + 1) = n! exactly for n = 1 .. 20: 0 violations',
 'gamma(0.5)^2 = pi: 1',
 'P(1, x) = 1 - exp(-x), Q(1, x) = exp(-x), P(1/2, x^2) = erf(x), P + Q = 1: 0 violations',
 'I_x(1, 1) = x, I_x(3, 1) = x^3, I_x(1, 4) = 1 - (1 - x)^4, I_x(a, b) + I_{1-x}(b, a) = 1: 0 violations',
 'incBeta is increasing in x on a grid of 101 points: 0 violations',
 'incGammaP is increasing in x: 0 violations',
 'stdNormalCdf(stdNormalQuantile(p)) = p, symmetry, erf(erfInv(p)) = p on 49 points: 0 violations',
]
edge = [('erf(inf)', '1'), ('erf(-inf)', '-1'), ('erf(nan)', 'nan'), ('erfc(inf)', '0'), ('erfc(-inf)', '2'), ('lgamma(0)', 'inf'), ('lgamma(-1)', 'inf'),
        ('lgamma(1)', '0'), ('lgamma(2)', '0'), ('lgamma(nan)', 'nan'), ('gamma(5)', '24'), ('gamma(0)', 'inf'), ('gamma(-1)', 'nan'), ('gamma(172)', 'inf'),
        ('digamma(0)', 'nan'), ('digamma(-2)', 'nan'), ('digamma(nan)', 'nan'), ('incGammaP(0, 1)', 'nan'), ('incGammaP(1, -1)', 'nan'),
        ('incGammaP(1, 0)', '0'), ('incGammaQ(1, 0)', '1'), ('incGammaP(2, inf)', '1'), ('incGammaP(nan, 1)', 'nan'), ('incBeta(-0.1, 1, 1)', 'nan'),
        ('incBeta(0, 1, 1)', '0'), ('incBeta(1, 1, 1)', '1'), ('incBeta(1.1, 1, 1)', 'nan'), ('incBeta(0.5, 0, 1)', 'nan'), ('incBeta(0.5, 1, nan)', 'nan'),
        ('stdNormalQuantile(0)', '-inf'), ('stdNormalQuantile(1)', 'inf'), ('stdNormalQuantile(0.5)', '0'), ('stdNormalQuantile(1.5)', 'nan'),
        ('stdNormalQuantile(-0.1)', 'nan'), ('stdNormalQuantile(nan)', 'nan'), ('erfInv(1)', 'inf'), ('erfInv(-1)', '-inf'), ('erfInv(0)', '0'),
        ('erfInv(1.5)', 'nan'), ('erfcInv(0)', 'inf'), ('erfcInv(2)', '-inf'), ('erfcInv(1)', '0'), ('erfcInv(3)', 'nan'), ('lbeta(0, 1)', 'inf'),
        ('lbeta(-1, 1)', 'nan'), ('lbeta(1, 1)', '0'), ('beta(2, 3)', '%.10g' % (1.0 / 12))]
for label, v in edge:
    out.append('%s %s' % (label, v))
sys.stdout.write('\n'.join(out) + '\n')
